                        repoInfo.owner + '/' + repoInfo.repo +
                        '/actions/runs/' + r.id + '/cancel || true'
                });
                cancelled.push(r);
                console.log('  🛑 cancelled stale validation run ' + r.id +
                            ' on superseded head ' +
                            String(r.head_sha).slice(0, 7) + ' (' +
